@dataclass
class RunnerConfig:
    cases: list[str]
    repeats: int = 3  # R, initial repeats per case
    max_repeats: int = 12  # cap for escalation
    workers: int = 4
    timeout: float = 600.0
    install_cmd: list[str] | None = field(default_factory=lambda: ["uv", "sync"])
    install_timeout: float = 600.0
    max_retries: int = 3
    backoff: float = 2.0
    models: dict[str, str] = field(default_factory=lambda: {
        "agent_model": os.environ.get("AGENT_MODEL") or DEFAULT_AGENT_MODEL,
        "judge_model": os.environ.get("JUDGE_MODEL") or DEFAULT_JUDGE_MODEL})
    # Confidence band: pass_rate >= good_min -> good, <= bad_max -> bad, else uncertain (escalate repeats).
    good_min: float = 0.85
    bad_max: float = 0.5
    classify: Callable[[float, int], str] | None = None  # hook: (pass_rate, n_runs) -> good|bad|uncertain
    env_file: str | None = None  # KEY=VALUE lines (API keys) injected into eval subprocesses; never logged
    worktree_root: str | None = None
    baseline: str | None = None  # absolute path to the target's evals baseline.json (kept outside the target repo)
    # Local Anthropic-compatible proxy (agentbisect llm-proxy): sets ANTHROPIC_BASE_URL + a dummy key in eval env.
    llm_proxy_url: str | None = field(default_factory=lambda: os.environ.get("AGENTBISECT_LLM_PROXY_URL") or None)


def config_from_env(cases: list[str], **kw) -> RunnerConfig:
    """RunnerConfig with operator overrides from the environment (budget control for live runs):
    AGENTBISECT_REPEATS, _MAX_REPEATS, _WORKERS, _ENV_FILE, _BASELINE."""
    env = os.environ
    for key, name, conv in (("repeats", "AGENTBISECT_REPEATS", int), ("max_repeats", "AGENTBISECT_MAX_REPEATS", int),
                            ("workers", "AGENTBISECT_WORKERS", int), ("env_file", "AGENTBISECT_ENV_FILE", str),
                            ("baseline", "AGENTBISECT_BASELINE", str)):
        if env.get(name) and key not in kw:
            kw[key] = conv(env[name])
    return RunnerConfig(cases=cases, **kw)


def default_classify(cfg: RunnerConfig) -> Callable[[float, int], str]:
    def f(rate: float, n: int) -> str:
        return "good" if rate >= cfg.good_min else "bad" if rate <= cfg.bad_max else "uncertain"
    return f


@contextlib.contextmanager
def worktree(repo: Path, sha: str, root: str | None = None) -> Iterator[Path]:
    """Detached worktree at sha in a temp dir; always removed and pruned, even on error."""
    tmp = Path(tempfile.mkdtemp(prefix="agentbisect-wt-", dir=root))
    path = tmp / "wt"
    try:
        subprocess.run(["git", "-C", str(repo), "worktree", "add", "--detach", str(path), sha],
                       capture_output=True, text=True, check=True)
        yield path
    finally:
        subprocess.run(["git", "-C", str(repo), "worktree", "remove", "--force", str(path)], capture_output=True)
        shutil.rmtree(tmp, ignore_errors=True)
        subprocess.run(["git", "-C", str(repo), "worktree", "prune"], capture_output=True)


def _load_env_file(path: str | None) -> dict[str, str]:
    out: dict[str, str] = {}
    if path and Path(path).exists():
        for line in Path(path).read_text().splitlines():
            line = line.strip()
            if line and not line.startswith("#") and "=" in line:
                k, v = line.split("=", 1)
                out[k.strip()] = v.strip().strip("'\"")
    return out


class Runner:
    def __init__(self, repo: str | Path, cfg: RunnerConfig, cache: VerdictCache,
                 executor: EvalExecutor | None = None, sleep: Callable[[float], None] = time.sleep):
        self.repo = Path(repo).resolve()
        self.cfg = cfg
        self.cache = cache
        self.executor = executor or SubprocessExecutor()
        self.sleep = sleep
        self.classify = cfg.classify or default_classify(cfg)
        self.eval_rounds = 0  # individual eval runs executed (not cache hits): the smart-vs-plain metric
        self._lock = threading.Lock()

    # -- install --

    def _install(self, wt: Path) -> None:
        if not self.cfg.install_cmd:
            return
        try:
            p = subprocess.run(self.cfg.install_cmd, cwd=wt, capture_output=True, text=True,
                               timeout=self.cfg.install_timeout, env=self._env(None, None, None))
        except subprocess.TimeoutExpired:
            raise BuildError(f"install timed out after {self.cfg.install_timeout}s")
        except OSError as e:
            raise BuildError(f"install could not start: {e}")
        if p.returncode != 0:
            raise BuildError(f"install failed (exit {p.returncode}): {(p.stderr or p.stdout)[-300:].strip()}")

    def _env(self, sha: str | None, run_id: str | None, case: str | None) -> dict[str, str]:
        env = {k: v for k, v in os.environ.items() if k not in ("VIRTUAL_ENV", "PYTHONPATH")}
        env.update(_load_env_file(self.cfg.env_file))
        # The neatlogs SDK logs "shutdown complete" to STDOUT at INFO, which corrupts the harness's JSON report.
        env.setdefault("NEATLOGS_LOG_LEVEL", "ERROR")
        if self.cfg.llm_proxy_url:
            env["ANTHROPIC_BASE_URL"] = self.cfg.llm_proxy_url
            env["ANTHROPIC_API_KEY"] = "agentbisect-proxy"
        for k, v in (("AGENTBISECT_COMMIT", sha), ("AGENTBISECT_RUN_ID", run_id), ("AGENTBISECT_CASE", case)):
            if v:
                env[k] = v
        return env

    # -- one case, with retries --

    def _run_case(self, wt: Path, sha: str, case: str, n: int, run_id: str) -> list[RunResult]:
        """Run `case` n times. Rate limits and timeouts retry (only the missing runs) with exponential backoff;
        runs still failing after max_retries become 'error' results, i.e. no verdict rather than a bad verdict."""
        results: list[RunResult] = []
        remaining = n
        last = "unknown"
        for attempt in range(self.cfg.max_retries + 1):
            req = CaseRequest(wt, sha, case, remaining, run_id, self._env(sha, run_id, case), self.cfg.timeout,
                              self.cfg.baseline)
            try:
                got = self.executor.run_case(req)
            except EvalInfraError as e:
                last = str(e)
            else:
                self._check_pins(got)
                retry = [r for r in got if r.status == "error" and RATE_LIMIT_RE.search(r.reason)]
                results += [r for r in got if r not in retry]
                remaining = remaining - len(got) + len(retry)
                if retry:
                    last = f"rate_limit: {retry[0].reason}"
                if remaining <= 0:
                    return results
            if attempt < self.cfg.max_retries:
                self.sleep(self.cfg.backoff * (2 ** attempt))
        return results + [RunResult(case, "error", reason=f"{last} (gave up after {self.cfg.max_retries + 1} attempts)")
                          for _ in range(remaining)]

    def _check_pins(self, results: list[RunResult]) -> None:
        for r in results:
            if r.status in ("skipped", "error"):
                continue
            for key in ("agent_model", "judge_model"):
                got = getattr(r, key)
                if got != self.cfg.models[key]:
                    raise ModelPinError(
                        f"{r.case_id}: {key} {got!r} != pinned {self.cfg.models[key]!r}; refusing to mix models")

    # -- one commit --

    def evaluate_commit(self, sha: str, run_id: str, cases: list[str] | None = None) -> CommitResult:
        """K cases x R repeats at `sha` in one worktree, `workers` cases in parallel. While the verdict is inside
        the confidence band, cases that disagree with themselves get doubled repeats up to max_repeats; if it is
        still uncertain the verdict is 'flaky'. Build/worktree failure => 'skip' (cached). Finished cases are
        cached immediately, so a crash mid-step loses at most the in-flight cases."""
        cases = list(cases or self.cfg.cases)
        models = self.cfg.models
        cached_skip = self.cache.get(sha, BUILD_CASE, models)
        if cached_skip:
            return CommitResult("skip", reason=cached_skip["skip"], from_cache=True)

        def have(case: str) -> dict:
            return self.cache.get(sha, case, models) or {}

        def need(case: str, target: int) -> int:
            e = have(case)
            return 0 if "skip" in e else max(0, target - e.get("passes", 0) - e.get("fails", 0))

        errors: dict[str, int] = {c: 0 for c in cases}
        wt_ctx = None
        wt: Path | None = None
        ran = False

        def work(cn: tuple[str, int]) -> None:
            case, n = cn
            results = self._run_case(wt, sha, case, n, run_id)
            p = sum(r.status == "pass" for r in results)
            f = sum(r.status == "fail" for r in results)
            errors[case] += sum(r.status == "error" for r in results)
            if results and all(r.status == "skipped" for r in results):
                self.cache.set_case_skip(sha, case, models, results[0].reason or "skipped by target")
                return
            with self._lock:
                self.eval_rounds += p + f
            self.cache.add_runs(sha, case, models, p, f,
                                [r.trace_id for r in results if r.trace_id and r.status in ("pass", "fail")])

        try:
            with step_span("evaluate_commit", sha=sha, run_id=run_id):
                active, target = cases, self.cfg.repeats
                while True:
                    todo = [(c, need(c, target)) for c in active]
                    todo = [t for t in todo if t[1] > 0]
                    if todo and wt_ctx is None:
                        wt_ctx = worktree(self.repo, sha, self.cfg.worktree_root)
                        try:
                            wt = wt_ctx.__enter__()
                            self._install(wt)
                        except (BuildError, subprocess.CalledProcessError) as e:
                            msg = str(e) if isinstance(e, BuildError) else \
                                f"git worktree failed: {(e.stderr or '').strip()[-200:]}"
                            self.cache.set_skip(sha, models, msg)
                            return CommitResult("skip", reason=msg)
                    if todo:
                        with ThreadPoolExecutor(max_workers=max(1, self.cfg.workers)) as pool:
                            list(pool.map(work, todo))
                        ran = True
                    stats = self._tally(sha, cases, errors)
                    passes = sum(t["passes"] for t in stats.values())
                    fails = sum(t["fails"] for t in stats.values())
                    if passes + fails == 0:
                        return CommitResult("skip", reason="no executed runs (all errored or skipped)",
                                            case_stats=stats)
                    rate = passes / (passes + fails)
                    band = self.classify(rate, passes + fails)
                    flaky = [c for c, t in stats.items() if t["passes"] and t["fails"]]
                    if band != "uncertain" or not flaky or target >= self.cfg.max_repeats:
                        break
                    target, active = min(self.cfg.max_repeats, target * 2), flaky
        finally:
            if wt_ctx is not None:
                wt_ctx.__exit__(None, None, None)

        traces = [t for c in stats for t in (have(c).get("trace_ids") or [])]
        verdict = {"good": "good", "bad": "bad"}.get(band, "flaky")
        return CommitResult(
            verdict, pass_rate=rate, trace_ids=traces, executed=passes + fails, repeats=target,
            flaky_cases=flaky, failing_cases=[c for c, t in stats.items() if t["fails"] and not t["passes"]],
            case_stats=stats, from_cache=not ran,
            reason=(f"pass_rate {rate:.2f} inside band ({self.cfg.bad_max}, {self.cfg.good_min}) after "
                    f"{target} repeats" if verdict == "flaky" else ""))

    def _tally(self, sha: str, cases: list[str], errors: dict[str, int]) -> dict[str, dict[str, int]]:
        out = {}
        for c in cases:
            e = self.cache.get(sha, c, self.cfg.models) or {}
            if "skip" in e:
                continue
            out[c] = {"passes": e.get("passes", 0), "fails": e.get("fails", 0), "errors": errors.get(c, 0)}
        return out
"""Durable state: investigation JSON + per-repo verdict cache under .agentbisect/, always written atomically."""
from __future__ import annotations

import hashlib
import json
import os
import tempfile
import threading
import uuid
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

from .models import BisectState, CommitResult, STATUSES
from .tracing import step_span

DEFAULT_DIR = ".agentbisect"
BUILD_CASE = "__build__"

TRANSITIONS = {
    "created": {"running", "failed"},
    "running": {"running", "paused", "failed", "culprit_found"},  # running->running: resume after a crash
    "paused": {"running", "failed"},
    "failed": {"running"},
    "culprit_found": {"fixing", "verifying", "reported", "running"},
    "fixing": {"verifying", "failed", "paused", "reported"},
    "verifying": {"fixing", "reported", "failed", "paused"},
    "reported": set(),
}


class StateError(RuntimeError):
    pass


def now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def atomic_write_json(path: Path, data: Any) -> None:
    """Write tmp file in the same dir, fsync, then rename over the target: readers never see a partial file."""
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=path.parent, prefix=path.name + ".", suffix=".tmp")
    try:
        with os.fdopen(fd, "w") as f:
            json.dump(data, f, indent=2, sort_keys=True)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, path)
    except BaseException:
        with _suppress():
            os.unlink(tmp)
        raise


class _suppress:
    def __enter__(self):
        return self

    def __exit__(self, *exc):
        return True


def cache_key(repo: str, sha: str, case: str, models: dict[str, str]) -> str:
    return "|".join([sha, case, models.get("agent_model", ""), models.get("judge_model", "")])


class VerdictCache:
    """Per (repo, sha, case, pinned model ids) run tallies, reusable across investigations on the same repo.

    Entry: {"passes": n, "fails": n, "trace_ids": [...]}; the build-failure skip is stored under case '__build__'
    as {"skip": reason}. Thread-safe; flushed to disk after every update."""

    def __init__(self, base: Path, repo: str):
        self.repo = str(Path(repo).resolve()) if repo else ""
        h = hashlib.sha256(self.repo.encode()).hexdigest()[:12]
        self.path = Path(base) / "cache" / f"{h}.json"
        self._lock = threading.Lock()
        self._data: dict[str, Any] = json.loads(self.path.read_text()) if self.path.exists() else {}

    def get(self, sha: str, case: str, models: dict[str, str]) -> dict[str, Any] | None:
        with self._lock:
            e = self._data.get(cache_key(self.repo, sha, case, models))
            return json.loads(json.dumps(e)) if e is not None else None

    def add_runs(self, sha: str, case: str, models: dict[str, str], passes: int, fails: int,
                 trace_ids: list[str]) -> dict[str, Any]:
        with self._lock:
            e = self._data.setdefault(cache_key(self.repo, sha, case, models),
                                      {"passes": 0, "fails": 0, "trace_ids": []})
            e["passes"] += passes
            e["fails"] += fails
            e["trace_ids"].extend(trace_ids)
            atomic_write_json(self.path, self._data)
            return json.loads(json.dumps(e))

    def set_case_skip(self, sha: str, case: str, models: dict[str, str], reason: str) -> None:
        with self._lock:
            self._data[cache_key(self.repo, sha, case, models)] = {"skip": reason}
            atomic_write_json(self.path, self._data)

    def set_skip(self, sha: str, models: dict[str, str], reason: str) -> None:
        with self._lock:
            self._data[cache_key(self.repo, sha, BUILD_CASE, models)] = {"skip": reason}
            atomic_write_json(self.path, self._data)


class StateStore:
    """Owns .agentbisect/: investigations/<id>.json and cache/<repo-hash>.json."""

    def __init__(self, base: str | Path = DEFAULT_DIR):
        self.base = Path(base)

    def _path(self, inv_id: str) -> Path:
        return self.base / "investigations" / f"{inv_id}.json"

    def cache(self, repo: str) -> VerdictCache:
        return VerdictCache(self.base, repo)

    def create(self, repo: str, **fields: Any) -> BisectState:
        st = BisectState(id=uuid.uuid4().hex[:10], repo=str(Path(repo).resolve()), created_at=now(), **fields)
        self.save(st)
        return st

    def save(self, st: BisectState) -> None:
        st.updated_at = now()
        atomic_write_json(self._path(st.id), st.to_dict())

    def load(self, inv_id: str) -> BisectState:
        p = self._path(inv_id)
        if not p.exists():
            raise StateError(f"no investigation '{inv_id}' in {p.parent}")
        return BisectState.from_dict(json.loads(p.read_text()))

    def list(self) -> list[BisectState]:
        d = self.base / "investigations"
        out = [BisectState.from_dict(json.loads(p.read_text())) for p in sorted(d.glob("*.json"))] if d.exists() else []
        return sorted(out, key=lambda s: s.created_at)

    # -- transitions and steps (each persists immediately) --

    def set_status(self, st: BisectState, status: str, error: str | None = None) -> None:
        if status not in STATUSES:
            raise StateError(f"unknown status '{status}'")
        if status not in TRANSITIONS[st.status]:
            raise StateError(f"illegal status transition {st.status} -> {status}")
        st.status = status
        st.error = error
        self.save(st)

    def begin_step(self, st: BisectState, kind: str, **info: Any) -> int:
        """Persist 'step N is in flight' BEFORE doing the work; a crash leaves it set so resume can redo the step."""
        st.in_flight = {"step": st.step + 1, "kind": kind, "started_at": now(), **info}
        self.save(st)
        return st.step + 1

    def end_step(self, st: BisectState, sha: str | None = None, result: CommitResult | None = None) -> None:
        if sha and result:
            st.results[sha] = result
        st.step += 1
        st.in_flight = None
        self.save(st)

    def record_result(self, st: BisectState, sha: str, result: CommitResult) -> None:
        st.results[sha] = result
        self.save(st)

    def log_context_tokens(self, st: BisectState, label: str, tokens: int) -> None:
        """Context tokens consumed by a step (with/without entire-graph is distinguished by label)."""
        st.context_tokens_per_step.append({"step": st.step + 1, "label": label, "tokens": int(tokens)})
        self.save(st)
        with step_span("context", label=label, context_tokens=int(tokens), step=st.step + 1):
            pass

    def interrupted(self, st: BisectState) -> bool:
        return st.status == "running" and st.in_flight is not None

    def resume(self, st: BisectState) -> dict[str, Any] | None:
        """Prepare a loaded investigation to continue. Returns the in-flight step that must be redone, if any."""
        if st.status == "reported":
            raise StateError("investigation already reported; nothing to resume")
        redo = st.in_flight
        self.set_status(st, "running")
        return redo
